<script setup>import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import{teacherApi,formatTime}from'../../api/teacher';const route=useRoute(),rows=ref([]),error=ref('');onMounted(async()=>{try{rows.value=(await teacherApi.gradingSubmissions(route.params.examId)).data}catch(e){error.value=e.message}})</script><template><p><RouterLink to="/teacher/grading">← 返回阅卷考试</RouterLink></p><header class="page-heading"><div><p class="eyebrow">SUBMISSIONS</p><h1>学生答卷</h1></div></header><p v-if="error" class="error-message">{{error}}</p><p v-if="!rows.length" class="empty-state">暂无已提交答卷。</p><div v-else class="table-scroll"><table><thead><tr><th>学生</th><th>提交状态</th><th>提交时间</th><th>阅卷状态</th><th>当前总分</th><th></th></tr></thead><tbody><tr v-for="s in rows" :key="s.id"><td>{{s.studentName}}</td><td><span class="badge">{{s.status}}</span></td><td>{{formatTime(s.submitTime)}}</td><td><span class="badge">{{s.gradingStatus}}</span></td><td>{{s.totalScore??'—'}}</td><td><RouterLink :to="'/teacher/grading/submissions/'+s.id">{{s.scorePublished?'查看':'阅卷'}} →</RouterLink></td></tr></tbody></table></div></template>
